// Normalize titles for the safety assertion: lowercase, unify dashes/quotes, collapse ws.
function norm(s) {
  return String(s || '')
    .replace(/[\u2012\u2013\u2014\u2015]/g, '-')      // dash variants -> -
    .replace(/[\u2018\u2019\u2032]/g, "'")             // curly single quotes -> '
    .replace(/[\u201C\u201D\u2033]/g, '"')             // curly double quotes -> "
    .toLowerCase().replace(/\s+/g, ' ').trim();
}

function mapFor(slug) {
  if (PART1_SLUG_RE.test(slug)) return { label: 'Part 1', scripts: PART1 };
  if (PART2_SLUG_RE.test(slug)) return { label: 'Part 2', scripts: PART2 };
  return null;
}

async function run() {
  await mongoose.connect(MONGODB_URI);
  console.log(`Connected.\nMode: ${APPLY ? 'APPLY (writing)' : 'DRY RUN (no changes)'}\n` + '='.repeat(90));

  const candidates = await LiveSession.find({
    sessionType: 'live-course',
    status: 'scheduled',
    $or: [{ slug: { $regex: PART1_SLUG_RE } }, { slug: { $regex: PART2_SLUG_RE } }]
  }).sort({ scheduledStart: 1 });

  console.log(`Found ${candidates.length} scheduled Ethics Table Talk sessions.\n`);

  let sessionsWritten = 0, segsSet = 0, segsDrift = 0, segsEmpty = 0, segsMissing = 0;

  for (const session of candidates) {
    const m = mapFor(session.slug);
    if (!m) continue;
    const start = session.scheduledStart
      ? new Date(session.scheduledStart).toLocaleString('en-US', { month:'short', day:'numeric', hour:'numeric', minute:'2-digit' })
      : '—';
    console.log(`\n▶ ${session.slug}  (${start})  [${m.label}]  — ${session.agenda?.length || 0} segments`);

    if (!session.agenda || !session.agenda.length) {
      console.log('   ⚠  no agenda rows — run applyEthicsTableTalkAgenda.js first. Skipping.');
      continue;
    }

    const newAgenda = [];
    let sessionChanged = false;

    for (const seg of session.agenda) {
      const plain = seg.toObject ? seg.toObject() : { ...seg };
      const entry = m.scripts.find(x => x.order === seg.order);

      if (!entry) {
        console.log(`   ?  [${seg.order}] "${seg.title}" — no script mapped for this order`);
        segsMissing++; newAgenda.push(plain); continue;
      }
      if (!entry.script) {
        console.log(`   ·  [${seg.order}] "${seg.title}" — intentionally empty (buffer)`);
        segsEmpty++; newAgenda.push(plain); continue;
      }
      if (norm(seg.title) !== norm(entry.expectTitle)) {
        console.log(`   ✗ DRIFT [${seg.order}] stored="${seg.title}"  expected="${entry.expectTitle}" — SKIPPED (title mismatch)`);
        segsDrift++; newAgenda.push(plain); continue;
      }
      // matched
      const already = plain.script && plain.script.trim() ? ' (overwriting existing)' : '';
      console.log(`   ✓ [${seg.order}] "${seg.title}" — ${entry.script.length} chars${already}`);
      newAgenda.push({ ...plain, script: entry.script });
      segsSet++; sessionChanged = true;
    }

    if (APPLY && sessionChanged) {
      const res = await LiveSession.updateOne(
        { _id: session._id, sessionType: 'live-course', status: 'scheduled' },
        { $set: { agenda: newAgenda } }
      );
      // read-back verify
      const fresh = await LiveSession.findById(session._id).lean();
      const filled = (fresh.agenda || []).filter(a => a.script && a.script.trim()).length;
      console.log(`   💾 written (matched=${res.matchedCount}, modified=${res.modifiedCount}); read-back: ${filled} segments now have script`);
      sessionsWritten++;
    }
  }

  console.log('\n' + '='.repeat(90));
  console.log(`Sessions: ${candidates.length}   Segments set: ${segsSet}   Drift-skipped: ${segsDrift}   Empty(buffer): ${segsEmpty}   Unmapped-order: ${segsMissing}`);
  if (APPLY) console.log(`Sessions written: ${sessionsWritten}`);
  else console.log('\nDRY RUN — nothing written. If titles all show ✓, re-run with --apply.');
  if (segsDrift > 0) console.log(`\n⚠ ${segsDrift} segment(s) skipped on title drift — paste this output and I'll reconcile the expected titles.`);

  await mongoose.disconnect();
}
run().catch(e => { console.error(e); process.exit(1); });
